from lib import *
recs=[
R(2166,"Casserole Terong Lezat",
"Jangan lewatkan menikmati resep ramah ginjal Casserole Terong Lezat pada makan malam Anda berikutnya.",
"8","1/2 cangkir",
["1 sendok makan minyak zaitun","1/4 cangkir mentega","1/2 cangkir bawang bombai","1/4 cangkir paprika hijau","5 siung bawang putih","1/2 sendok teh cabai cayenne","1/2 sendok teh lada hitam","1/2 sendok teh thyme bubuk","8 cangkir terong","1/2 cangkir remah roti tawar","1 butir telur besar"],
["Panaskan oven terlebih dahulu hingga 350° F.","Cincang bawang bombai dan paprika. Iris bawang putih dan potong terong menjadi dadu.","Dalam wajan besar, panaskan minyak dan mentega dengan api sedang. Tumis bawang bombai, paprika hijau, dan bawang putih bersama cabai cayenne dan lada hitam.","Tambahkan thyme dan terong ke dalam bahan, dan masak hingga terong melunak, sering diaduk.","Sisihkan 2 sendok makan remah roti untuk taburan. Tambahkan sisa remah roti ke terong dan masak 15 menit.","Kocok telur dan tambahkan ke campuran, aduk cepat agar telur tidak menggumpal.","Letakkan dalam wadah casserole. Taburkan sisa remah roti di atas campuran, dan panggang selama 25 menit."],
["Dua terong sedang menghasilkan sekitar 8 cangkir.","Sesuaikan cabai cayenne dengan selera Anda.","Simpan sisa casserole di lemari es atau freezer untuk hidangan cepat nanti."],
["1 sayuran, kalium sedang","3 lemak"]),
R(2167,"Punch Raspberry Segar",
"Selalu memuaskan saat tujuan yang menantang tercapai, seperti mendapatkan hasil lab yang baik saat mengikuti rencana makan ramah ginjal. Leanne, ahli gizi DaVita dari Pennsylvania, telah menetapkan banyak tujuan yang berhasil ia capai. Setiap pencapaian, Leanne merayakannya bersama teman, keluarga, pasien, dan rekan tim DaVita. Perayaannya selalu menghadirkan Punch Raspberry Segar buatannya. Bersoda, berbusa, mudah dibuat, dan membawa manis yang lezat bagi semua orang.",
"24","6 ons (3/4 cangkir)",
["46 ons jus nanas kaleng","6 ons konsentrat limun merah muda beku","16 ons sherbet atau sorbet raspberry","2 liter ginger ale diet, dingin","10 ons raspberry merah beku, sudah dicairkan"],
["Dalam mangkuk punch besar, campurkan jus, limun, sherbet atau sorbet, dan ginger ale diet.","Aduk bersama raspberry yang sudah dicairkan beserta cairannya (tanpa ditiriskan)."],
["Punch akan berbusa saat sherbet mulai mencair. Pastikan menggunakan mangkuk punch yang cukup besar. Aduk hingga tercampur saat sherbet mencair.","Analisis resep mencakup sherbet."],
["1 buah, kalium rendah"]),
R(2168,"Ayam Maple-Jeruk",
"Meskipun rasanya sangat lezat, Ayam Maple-Jeruk cocok untuk diet ginjal maupun rencana makan penderita diabetes.",
"4","1 dada ayam",
["2 sendok makan minyak zaitun","4 dada ayam tanpa tulang dan tanpa kulit","1/2 sendok teh garam","1/4 sendok teh lada hitam","1/4 cangkir sirup maple","1 sendok makan marmalade jeruk","1/4 cangkir air lemon segar","1 sendok makan peterseli segar, dicincang (opsional)","1 batang daun bawang, dicincang (opsional)"],
["Panaskan minyak dalam wajan antilengket dengan api sedang. Saat panas, masukkan ayam dan bumbui dengan garam dan lada. Masak hingga ayam kecokelatan dan tidak lagi bening di seluruh bagian. Pindahkan ke piring saji yang hangat.","Buang minyak di wajan dan letakkan di atas api sedang. Tambahkan sirup maple, dan panaskan hingga menggelembung; aduk marmalade dan tambahkan air satu buah lemon. Didihkan hingga saus mengental, sekitar 1 menit.","Tuang saus di atas ayam. Hiasi dengan peterseli segar dan daun bawang jika diinginkan."],
["Cindy berkata “Suami saya dan saya suka hidangan ini. Mudah dan cepat, hanya perlu sekitar 10 menit untuk menyiapkannya.”","Gunakan sirup maple bebas gula untuk menurunkan karbohidrat jika Anda menderita diabetes. Karbohidrat berkurang menjadi 10 gram dan hitungan karbohidrat adalah 1/2.","Belilah dada ayam besar jika Anda menjalani diet dialisis dan membutuhkan protein tinggi. Resep dianalisis dengan empat dada ayam 5 ons.","Untuk penyakit ginjal kronis (PGK) non-dialisis dengan diet rendah protein, kurangi ukuran porsi menjadi 1/2 dada ayam atau timbang porsi sesuai rencana makan Anda."],
["4-1/2 daging","1 berkalori tinggi"]),
R(2172,"Pretzel Lembut",
"Nikmati resep ramah ginjal Pretzel Lembut dengan mustard rendah natrium untuk camilan sore yang istimewa.",
"24","1",
["2 cangkir air hangat","2 bungkus ragi kering aktif","4 sendok makan minyak canola","5-1/2 cangkir tepung terigu putih serbaguna (dibagi)","6 cangkir air","3 sendok makan soda kue","1/4 cangkir mustard"],
["Larutkan ragi dalam air hangat dan diamkan selama 10 menit.","Tambahkan minyak canola dan setengah tepung. Aduk hingga benar-benar tercampur. Tambahkan sisa tepung dan uleni selama 5 menit.","Tutup dan biarkan adonan beristirahat selama 1 jam.","Bagi adonan menjadi 24 bagian. Gulung hingga panjang 18” dan pilin menjadi bentuk pretzel. Biarkan mengembang selama 30 menit.","Panaskan oven terlebih dahulu hingga 475° F.","Tambahkan soda kue ke dalam 6 cangkir air dalam panci besar dan didihkan.","Masukkan pretzel ke dalam air mendidih selama 1 menit lalu pindahkan ke loyang yang disemprot semprotan masak antilengket.","Panggang selama 12 menit.","Sajikan setiap pretzel dengan 1/2 sendok teh mustard."],
["Pilih merek mustard yang paling rendah natrium.","Anda mungkin perlu menambahkan air agar permukaan air dalam panci tetap tinggi. Masukkan pretzel dalam jumlah kecil."],
["1-1/2 makanan pokok bertepung"]),
R(2173,"Wafel Belgia",
"Putih telur kocok adalah rahasia membuat Wafel Belgia ini ringan dan empuk, selain itu juga menjaga kandungan fosfor lebih rendah dibandingkan adonan wafel instan. Taburi dengan beri segar, sirup, atau cukup taburan gula bubuk dan nikmati!",
"6","1 wafel besar",
["2 butir telur besar","2 cangkir tepung kue","3/4 sendok teh soda kue","3/4 cangkir krim asam","3/4 cangkir susu rendah lemak 1%","2 sendok teh ekstrak vanila","4 sendok makan mentega tanpa garam","2 sendok makan gula pasir","6 sendok makan gula bubuk"],
["Panaskan cetakan wafel. Dalam mangkuk pencampur, campurkan tepung kue dan soda kue lalu sisihkan. Pisahkan putih telur dan kuning telur. Kocok kuning telur, krim asam, susu, dan ekstrak vanila. Lelehkan mentega lalu campurkan ke dalam campuran krim asam.","Dalam mangkuk lain, kocok putih telur dengan mixer tangan pada kecepatan sedang hingga terbentuk puncak lembut, sekitar 3 menit. Tambahkan gula pasir ke putih telur dan terus kocok hingga terbentuk puncak kaku, sekitar 3 hingga 4 menit lagi.","Kocok campuran krim asam ke dalam campuran tepung hingga baru tercampur. Lipat perlahan putih telur kocok hingga adonan halus; jangan diaduk berlebihan.","Tuang sekitar 1/2 cangkir adonan ke cetakan wafel, tutup dan masak sekitar 3 menit. Sajikan wafel dengan gula bubuk. Topping lain yang disarankan meliputi beri segar, krim kocok, selai, atau sirup."],
["Sirup maple dapat digunakan sebagai pengganti gula bubuk. Jika menggunakan sirup maple, 1/4 cangkir mengandung 54 g karbohidrat dan 170 mg kalium. Beberapa sirup pancake light atau tiruan mungkin mengandung bahan tambahan fosfor; bacalah daftar bahan untuk menghindari bahan tambahan tersebut.","Stroberi, blueberry, dan atau raspberry juga dapat menjadi pilihan topping wafel ini. 1/2 cangkir beri menambahkan 5-10 g karbohidrat dan 55-110 mg kalium, tergantung buah yang digunakan.","Jika Anda membatasi karbohidrat, ubah porsi menjadi 1/2 wafel dan taburi dengan beri dan krim kocok (30-35 gram karbohidrat)."],
["2 makanan pokok bertepung","2 lemak","1/2 berkalori tinggi"]),
R(2175,"Salsa Blender",
"Salsa rendah kalium ini mudah dibuat berkat penggunaan blender. Blender dan sajikan!",
"10","1/4 cangkir",
["1/2 bawang bombai kecil","1 siung bawang putih","1 kaleng tomat potong dadu 14 ons","1 kaleng tomat Ro-tel® tanpa tambahan natrium 10 ons","1 jalapeno","1 sendok teh madu","1/4 sendok teh jintan bubuk","1 sendok makan kolantro segar","Air 1 buah jeruk nipis"],
["Cincang kasar bawang bombai. Kupas dan memarkan bawang putih.","Campurkan semua bahan dalam blender (bisa juga menggunakan food processor) dan pulse selama 30 detik atau hingga mencapai konsistensi salsa yang diinginkan. Sajikan dengan keripik tortilla atau hidangan Amerika Latin favorit Anda!"],
["Herba dan rempah dapat disesuaikan dengan selera. Biji jalapeno dapat dibuang untuk mengurangi tingkat pedas.","Resep tahan hingga satu minggu di lemari es."],
["1/2 sayuran, kalium rendah"]),
R(2176,"Dip Artichoke Creamy",
"Sajikan dip artichoke creamy ini di pesta Anda berikutnya. Resep lezat dan ramah ginjal ini untuk orang yang menjalani diet ginjal.",
"10","2 sendok makan",
["1 cangkir hati artichoke beku","1/4 cangkir mayones","1/4 cangkir krim asam","2 sendok makan krim keju","1 siung bawang putih besar","2 sendok teh saus pedas","1 sendok makan keju Parmesan"],
["Panaskan oven terlebih dahulu hingga 375º F.","Letakkan hati artichoke dalam panci, tutup dengan air dan didihkan. Kecilkan api ke sedang dan masak selama 6 menit. Tiriskan dan bilas dengan air dingin agar dingin.","Cincang hati artichoke.","Dalam mangkuk sedang, campurkan mayones, krim asam, krim keju, saus pedas, dan siung bawang putih yang dihaluskan. Tambahkan hati artichoke dan aduk hingga tercampur. Pindahkan campuran ke loyang.","Taburi dengan keju Parmesan. Masukkan ke oven dan panggang selama 30 menit atau hingga bagian atas menggelembung."],
["Jika menggunakan artichoke kaleng atau botol dalam air sebagai pengganti yang beku, carilah merek yang paling rendah natrium. Bilas dengan baik untuk membantu mengurangi natrium.","Coba dip ini pada irisan baguette panggang, seledri renyah, atau dengan biskuit rendah natrium favorit Anda. Pilih biskuit beras atau biskuit bebas gluten lainnya jika Anda menjalani diet bebas gluten.","Saus Tabasco© adalah salah satu saus cabai dengan natrium terendah."],
["1/2 sayuran, kalium sedang","2 lemak"]),
R(2177,"Panini Kalkun",
"Ahli gizi ginjal DaVita, Erica dari Wisconsin, menawarkan resepnya untuk Panini Kalkun Sehari Setelah Thanksgiving. Anda tidak perlu menunggu Thanksgiving untuk mencoba Panini Kalkun — sisa kalkun apa pun bisa digunakan. Makanan lezat tidak perlu hanya disediakan untuk hari raya.",
"1","1 sandwich",
["2 iris roti Italia","2 sendok teh mentega tanpa garam","2 iris keju Swiss Sargento® Ultra Thin","2-1/2 ons kalkun, matang, tanpa garam","2 sendok teh saus cranberry berbuah utuh"],
["Panaskan wajan panggang atau mesin Panini dengan api sedang.","Oleskan setiap potong roti dengan satu sendok teh mentega.","Pada sisi roti yang tidak diolesi mentega, susun satu iris keju, irisan sisa kalkun, saus cranberry, dan sisa iris keju. Letakkan potongan roti lainnya di atas, sisi yang diolesi mentega menghadap ke atas.","Letakkan sandwich di wajan atau di mesin Panini. Panggang sandwich 5 menit di mesin Panini atau hingga keemasan dan garing.","Jika menggunakan wajan, tekan sandwich dengan tutup wajan. Balik sandwich setelah sekitar 3 menit atau saat bagian bawah sudah garing sepenuhnya. Masak sisi lainnya sekitar 3 menit atau hingga garing."],
["Untuk rencana makan rendah protein, kurangi kalkun menjadi 1 ons dan gunakan 1 iris keju. Tambahkan lebih banyak saus cranberry untuk kalori tambahan.","Setiap iris keju beratnya .32 ons sehingga dua iris sama dengan sekitar 2/3 ons total.","Ahli gizi Erica berkata \"Saya suka mesin Panini saya! Saya menemukannya di obral barang bekas seharga sekitar $3 dan sudah sangat sering dipakai. Saya dengar pemanggang George Foreman atau peralatan dapur serupa juga bekerja sama baiknya. Alat ini membuat sandwich panggang biasa Anda menjadi sedikit lebih istimewa.\""],
["3-1/2 daging","2 makanan pokok bertepung"]),
R(2178,"Salad Rotini (rendah protein)",
"Bersenang-senanglah dengan bentuk spiral pasta rotini saat membuat resep ramah ginjal ini, Salad Rotini (rendah protein).",
"8","1/2 cangkir",
["4 ons pasta rotini, mentah","1-1/4 cangkir bawang bombai","4 butir telur besar","1 mentimun sedang","1/2 cangkir mayones","1/2 sendok teh lada hitam","1 sendok makan mustard kering","1/3 sendok teh garam","1 sendok teh mustard siap pakai","1/2 cangkir gula","1/3 cangkir cuka"],
["Masak rotini sesuai petunjuk pada kemasan tanpa garam. Tiriskan dan bilas dengan air dingin.","Rebus telur hingga matang keras, dinginkan dan kupas.","Cincang bawang bombai dan telur; potong dadu mentimun.","Dalam mangkuk besar, campurkan rotini, bawang bombai, telur, mentimun, dan lada.","Campurkan bahan-bahan yang tersisa untuk membuat dressing.","Tambahkan dressing buatan sendiri ke pasta dan aduk rata.","Dinginkan di lemari es sebelum disajikan."],
["Rotini adalah pasta berbentuk spiral kecil seperti pembuka botol.","4 ons rotini kering menghasilkan 2-1/2 cangkir saat matang."],
["2 makanan pokok bertepung","1 sayuran, kalium rendah","2 lemak"]),
R(2182,"Burger Daging Sapi Klasik (Protein Lebih Rendah)",
"Lisa, ahli gizi ginjal DaVita dan mantan koki dari New York, membagikan resep burger daging sapi klasik yang lezat dan ramah ginjal. Sangat cocok untuk makan siang dan begitu penuh rasa sehingga tidak memerlukan saus tambahan.",
"6","1 burger",
["1 pon daging sapi giling tanpa lemak","1 cangkir bawang bombai manis, dicincang halus","1 butir telur besar","3 sendok makan campuran bumbu Mrs. Dash® Southwest Chipotle","6 roti burger"],
["Panaskan panggangan terlebih dahulu sesuai petunjuk pabrik.","Dalam mangkuk besar, campurkan daging sapi giling, bawang bombai, telur, dan bumbu Mrs. Dash® hingga semua bahan tercampur rata.","Bagi adonan daging sapi menjadi 6 patty berukuran sama.","Panggang hingga suhu dan tingkat kematangan yang diinginkan.","Letakkan di atas roti burger."],
["Burger ini tidak memerlukan saus tomat atau mustard. Penuh rasa!","Gunakan campuran bumbu Mrs. Dash® favorit Anda.","Satu bawang bombai besar menghasilkan 1 cangkir cincang.","Versi protein lebih rendah dari Burger Luar Biasa Lisa ini memiliki porsi burger yang lebih kecil dibandingkan resep asli di DaVita.com. Nutrisi telah disesuaikan untuk mencerminkan perubahan ini."],
["2 daging","2 makanan pokok bertepung","1/2 sayuran, kalium sedang"]),
R(2184,"Mangkuk Sayur Kebun",
"Hidangan satu mangkuk ini memberi Anda makanan bergaya vegetarian yang seimbang dalam satu mangkuk.",
"1","1 mangkuk",
["1 burger sayur kebun beku","1 cangkir sayuran campur beku (brokoli, kembang kol, wortel)","1 sendok makan krim asam light","1 sendok teh honey mustard"],
["Masak burger sayur kebun sesuai petunjuk kemasan, baik di atas kompor maupun microwave. Setelah matang sempurna, potong menjadi potongan seukuran sekali suap dan sisihkan.","Masak sayuran sesuai petunjuk kemasan. Jika Anda membeli kantong kukus, microwave kantong sesuai petunjuk kemasan dan microwave Anda.","Campurkan krim asam dan honey mustard dalam mangkuk kecil. Letakkan 1 cangkir sayuran dalam mangkuk, susun burger sayur kebun di atasnya dan siram dengan campuran krim asam/honey mustard. Aduk semuanya dan nikmati!"],
["Carilah burger sayur kebun atau sayuran beku dengan kandungan natrium terendah. Resep ini diuji dengan Morningstar® Garden Veggie Burger.","Sayuran campur rendah kalium apa pun atau satu jenis sayuran saja juga cocok. Sayuran beku dalam kantong kukus praktis dan rendah natrium. Coba brokoli, kembang kol, jagung campur, buncis, dll.","Carilah honey mustard plain atau varian rendah natrium."],
["1 protein","1 makanan pokok bertepung","2 sayuran, kalium sedang"]),
R(2187,"Torte Buah Buttercream",
"Torte Buah Buttercream adalah dessert untuk tamu yang ramah ginjal, kaya rasa dan kalori namun begitu lezat sehingga Anda ingin membagikan resep rendah kalium ini.",
"20","potongan 2-1/2\" x 2-1/4\"",
["1-1/2 cangkir mentega tanpa garam","2 cangkir remah graham cracker","1/4 cangkir gula pasir","2 cangkir gula bubuk","1/2 sendok teh garam","2 sendok teh vanila","1/2 cangkir creamer half & half","20 ons nanas hancur kaleng dalam jus","2 cangkir stroberi segar","8 ons topping kocok"],
["Panaskan oven terlebih dahulu hingga 350° F.","Lelehkan 1/2 cangkir mentega; campurkan dengan remah graham cracker dan gula pasir. Sisihkan 1/4 cangkir campuran kulit untuk digunakan nanti.","Tekan sisa campuran ke dalam loyang 9” x 13” yang tidak diolesi lemak.","Panggang selama 15 menit; letakkan loyang di lemari es untuk didinginkan.","Kocok sisa 1 cangkir mentega yang telah lunak, gula bubuk, garam, vanila, dan creamer hingga mengembang.","Ratakan campuran isian di atas kulit yang sudah dingin. Dinginkan sekitar 15 menit.","Tiriskan nanas; iris stroberi. Ratakan nanas dan stroberi di atas isian. Dinginkan selama 30 menit.","Sebelum disajikan ratakan topping kocok di atas buah. Taburi dengan sisa 1/4 cangkir campuran kulit graham cracker yang disisihkan."],
["Satu batang mentega sama dengan 1/2 cangkir.","Satu keranjang stroberi segar ukuran satu pint menghasilkan 2 cangkir stroberi iris."],
["1/2 makanan pokok bertepung","1/2 buah, kalium rendah","1 berkalori tinggi","3 lemak"]),
R(2190,"Upma Sayuran",
"Upma Sayuran adalah hidangan ramah ginjal yang biasanya disajikan saat sarapan, tetapi keluarga Anda juga akan menyukai hidangan biji-bijian dan sayuran ini untuk makan siang atau makan malam.",
"2","1-1/4 cangkir",
["1 sendok makan kacang mete","1/4 cangkir bawang bombai","1/4 cangkir wortel","1/4 cangkir tomat","1 sendok makan kolantro","1 sendok makan cabai jalapeno","1 sendok teh jahe","2 sendok makan minyak sayur","1/2 sendok teh biji mustard","1 sendok makan kacang arab belah (chana dahl)","1 sendok teh kacang hitam belah (urad dahl)","1/2 cangkir sereal Cream of Wheat® masak cepat, mentah","1 sendok teh jintan bubuk","1/4 cangkir kacang polong hijau","1 sendok makan daun kari","1/4 sendok teh garam","1 cangkir air","1 sendok teh air lemon"],
["Cincang kacang mete. Potong dadu bawang bombai, wortel, dan tomat. Cincang kolantro dan cabai jalapeno. Parut jahe.","Panaskan minyak sayur dalam wajan wok di atas kompor dengan api sedang hingga besar. Saat minyak mulai berubah warna, tambahkan biji mustard. Saat biji mustard mulai meletup, kecilkan api ke sedang-kecil dan tambahkan kacang arab belah (chana dahl) dan kacang hitam (urad dahl). Aduk bahan dengan sendok kayu dan tambahkan kacang mete cincang. Goreng hingga kacang dan kacang mete berwarna cokelat keemasan. Tambahkan jintan.","Tambahkan bawang bombai dan tumis hingga cokelat keemasan. Tambahkan tomat, wortel, kacang polong, daun kari, kolantro, dan jahe dan masak hingga tomat melunak.","Tambahkan cream of wheat dan masak selama 2-3 menit.","Didihkan air. Tambahkan garam dan aduk ke dalam air mendidih tanpa membentuk gumpalan. Campuran menjadi berkonsistensi semi-padat. Terus aduk hingga air menguap. Kecilkan api, tutup dan masak selama 3-4 menit.","Matikan api. Percikkan air lemon dan gemburkan dengan garpu. Bagi menjadi 2 porsi dan sajikan."],
["Chana dahl, urad dahl, biji mustard, jintan, dan daun kari tersedia di toko bahan makanan India.","Upma adalah hidangan sarapan terkenal di India Selatan. Selain semolina (farina, Cream of Wheat®), upma mengandung bumbu dan sayuran."],
["2 makanan pokok bertepung","2 sayuran, kalium sedang","3 lemak"]),
R(2191,"Udang Super Tuesday",
"Para pecinta protein, perhatian! Udang dan steak mendapat perlakuan istimewa dalam resep ini oleh ahli gizi ginjal DaVita, Carol dari California. Udang Super Tuesday ramah ginjal dan mudah dibuat dengan petunjuk memasak langkah demi langkah dari Carol. Sederhana, cepat, dan luar biasa!",
"4","1 cangkir",
["4 ons pasta, mentah","2 sendok makan bawang bombai","2 siung bawang putih","1 sendok makan minyak zaitun","1/4 cangkir tomat kering dalam minyak","12 ons udang sedang, mentah","8 ons kacang polong pipih beku,","1/4 cangkir keju feta"],
["Masak pasta sesuai petunjuk kemasan, tanpa garam. Tiriskan dan sisihkan.","Cincang halus bawang bombai dan bawang putih. Kupas dan buang usus udang.","Tumis bawang bombai dan bawang putih dalam minyak hingga kecokelatan ringan.","Tambahkan tomat kering, udang, dan kacang polong pipih.","Masak hingga udang berubah warna (tetapi kacang polong pipih tetap renyah).","Campurkan udang dan pasta.","Taburi keju feta di atasnya dan sajikan."],
["Empat ons pasta kering menghasilkan 2 cangkir saat matang.","Udang beku dapat digunakan sebagai pengganti udang segar."],
["3 daging","1-1/2 makanan pokok bertepung","1 sayuran, kalium rendah"]),
R(2193,"Dip Cranberry dengan Buah Segar",
"Dip Cranberry dengan Buah Segar adalah camilan ramah ginjal yang rendah kalium dan cara yang bagus untuk mendapatkan vitamin dan serat dari buah. Tim ahli gizi ginjal DaVita menghadirkan resep makanan pesta yang lezat ini untuk dinikmati bersama teman atau sebagai camilan sendiri.",
"24","2 sendok makan dip, 2 iris apel, 2 iris pir dan 3 potong nanas",
["8 ons krim asam","1/2 cangkir saus cranberry berbuah utuh","1/4 sendok teh pala","1/4 sendok teh jahe bubuk","4 cangkir nanas segar","4 apel sedang","4 pir sedang","1 sendok teh air lemon"],
["Masukkan krim asam, saus cranberry, pala, dan jahe ke dalam food processor dan proses hingga tercampur rata. Pindahkan ke mangkuk kecil.","Potong nanas menjadi potongan seukuran sekali suap. Potong apel dan pir masing-masing menjadi 12 iris. Aduk irisan apel dan pir dengan air lemon agar tidak menjadi cokelat.","Tata buah di piring saji dengan mangkuk dip di tengah. Dinginkan hingga siap disajikan."],
["Simpan sisa dip di lemari es hingga 3 hari."],
["1 buah, kalium rendah"]),
]
save(3,recs)
